INSERT INTO teamchat.memories (tenant_id,memory_id,key,value,created_by,created_at,source_room_id) VALUES ('northside-outfitters','mem-n-001','cooling_accessory_bundling_policy','{"decision":"cooling units are ranged with energy accessories as a single planogram block","rationale":"attachment rate rose from 11% to 29% in the 2025 pilot","agreed_by":"Sarah Keane and the merchandising director","applies_from":"2026-03-14","review":"annually before season set"}','Sarah Keane','2026-03-14T10:22:00Z','category-strategy') ON CONFLICT DO NOTHING;
