INSERT INTO teamchat.memories (tenant_id,memory_id,key,value,created_by,created_at,source_room_id) VALUES ('northside-outfitters','mem-n-003','unspecified_line_rule','{"rule":"an unspecified line may not be used as a permanent range entry beyond one season","reason":"it carries no margin class and hides the gap from reporting","agreed_by":"buying team","effective":"2025-11-02"}','L. Osei','2025-11-02T09:40:00Z','assortment-review') ON CONFLICT DO NOTHING;
